import sys

class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def get_count(head):
    count = 0
    current = head
    while current:
        count += 1
        current = current.next
    return count

def sorted_list_to_bst_helper(nodes, start, end):
    if start > end:
        return None

    mid = (start + end) // 2
    left_child = sorted_list_to_bst_helper(nodes, start, mid - 1)

    root = TreeNode(nodes[mid])
    root.left = left_child

    root.right = sorted_list_to_bst_helper(nodes, mid + 1, end)

    return root

def sortedListToBST(head):
    if not head:
        return None

    nodes = []
    current = head
    while current:
        nodes.append(current.val)
        current = current.next

    return sorted_list_to_bst_helper(nodes, 0, len(nodes) - 1)

def preorder_traversal(root):
    result = []
    if root:
        result.append(root.val)
        result.extend(preorder_traversal(root.left))
        result.extend(preorder_traversal(root.right))
    return result

def main():
    input_data = sys.stdin.read().strip()
    if not input_data:
        return

    values = list(map(int, input_data.split()))

    if not values:
        return

    head = None
    tail = None
    for val in values:
        new_node = ListNode(val)
        if not head:
            head = new_node
            tail = new_node
        else:
            tail.next = new_node
            tail = new_node

    bst_root = sortedListToBST(head)
    preorder = preorder_traversal(bst_root)

    print(" ".join(map(str, preorder)))

if __name__ == "__main__":
    main()
